"""Original format-comparison and JSON-layer guides with shared, checked examples."""
from pathlib import Path
import html,json
FIXTURES=json.loads((Path(__file__).parent/'guide-fixtures.json').read_text())
EXTRA_GUIDES=[
 {'slug':'guides/yaml-vs-json','title':'YAML vs JSON — Types, Syntax & Conversion Trade-offs','heading':'YAML vs JSON: syntax, types and conversion','description':'Compare YAML and JSON with the same configuration. Check strings, booleans, comments, duplicate keys and aliases using complete, local examples.','published':'2026-11-27','category':'Data formats','label':'YAML vs JSON'},
 {'slug':'guides/json-double-encoding','title':'JSON Backslashes & Double Encoding — A Practical Guide','heading':'Why JSON has backslashes: escaping and double encoding','description':'Diagnose escaped JSON strings and double encoding. Inspect one layer, preserve real backslashes and identify when a JSON value should stay a string.','published':'2026-11-27','category':'Data formats','label':'JSON encoding layers'},
]
JS_SNIPPET='''const record = { id: "001", ready: true };
// This example deliberately serializes an object twice.
const body = JSON.stringify(JSON.stringify(record));
const first = JSON.parse(body);
console.log(typeof first); // string

// A second parse is deliberate here: we know this sample holds an object.
const second = JSON.parse(first);
console.log(typeof second); // object
console.log(second.id); // 001'''
PY_SNIPPET='''import json

record = {"id": "001", "ready": True}
body = json.dumps(json.dumps(record))
first = json.loads(body)
print(type(first).__name__)  # str

# Decode again only because this known sample is a serialized object.
second = json.loads(first)
print(type(second).__name__)  # dict
print(second["id"])  # 001'''
FIELD_SNIPPET='''const envelope = {
  payload: '{"id":"001"}',
  note: '{"keep":"this is ordinary text"}'
};
// The producer's contract identifies payload as JSON text.
const payload = JSON.parse(envelope.payload);
console.log(payload.id); // 001
console.log(typeof envelope.note); // string'''

def header(slug,label,title,deck,toc):
 return '<article class="guide-article"><header class="guide-header"><nav class="guide-breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a><span>/</span><a href="/guides/">Guides</a><span>/</span><span aria-current="page">'+label+'</span></nav><span class="eyebrow">DATA FORMATS · WORKED GUIDE</span><h1>'+title+'</h1><p class="guide-deck">'+deck+'</p><p class="guide-byline">By <a href="/about/">ParseCove</a> · Published <time datetime="2026-11-27">27 November 2026</time></p></header><nav class="guide-toc" aria-label="On this page"><strong>On this page</strong>'+''.join('<a href="#'+i+'">'+n+'</a>' for i,n in toc)+'</nav>'

def demo(kind,copy):
 cases=FIXTURES[kind];first=cases[0]
 if kind=='yaml':result=json.dumps(first['expected'],ensure_ascii=False,indent=2);input_label='YAML document';result_label='JSON document';intro='Choose a complete example. The output is generated by the same YAML 1.2 core parser and validation rules as the conversion tool.'
 else:result=json.loads(first['input']);input_label='JSON source text';result_label='Result after one parse';intro='Choose a known example and inspect one parse. The inspector never recursively rewrites string fields or guesses which values should change type.'
 data=json.dumps(cases,ensure_ascii=False).replace('<','\\u003c')
 return '<section class="format-demo guide-section" id="format-lab"><div class="result-head"><h2>'+('Try the types' if kind=='yaml' else 'Inspect one encoding layer')+'</h2><button class="button small" id="format-reset">Reset example</button></div><p>'+intro+'</p><label for="format-case">Complete example</label><select id="format-case">'+''.join('<option value="'+c['id']+'">'+html.escape(c['label'])+'</option>' for c in cases)+'</select><div class="format-demo-grid"><div><div class="result-head"><label for="format-input">'+input_label+'</label>'+copy('format-input','Copy input')+'</div><textarea id="format-input" class="mono" rows="12" readonly>'+html.escape(first['input'])+'</textarea></div><div><div class="result-head"><label for="format-output">'+result_label+'</label>'+copy('format-copy')+'</div><textarea id="format-output" class="mono" rows="12" readonly>'+html.escape(result)+'</textarea><span id="format-copy" hidden>'+html.escape(result)+'</span></div></div><p class="error" id="format-error" role="alert" hidden></p><p id="format-status" class="result-sub" role="status">'+('YAML 1.2 core: supported values are preserved.' if kind=='yaml' else 'After one parse: string. One top-level string layer was decoded.')+'</p><p id="format-explanation">'+first['note']+'</p><noscript><p class="hint">JavaScript switches the examples. The complete default example and all reference sections remain readable.</p></noscript><script type="application/json" id="format-cases">'+data+'</script></section>'

def yaml_json_guide(code_example,faq,copy):
 body=header('yaml-vs-json','YAML vs JSON',EXTRA_GUIDES[0]['heading'],'YAML and JSON can describe the same supported values with different notation. The practical question is which types, conventions and parser behavior your configuration or data exchange needs.',[('same-data','Same data'),('format-lab','Try the types'),('type-rules','Type rules'),('conversion-loss','What conversion loses'),('choose-format','Choose a format'),('format-faq','FAQ')])
 body+='''<section class="guide-section" id="same-data"><h2>Start with one configuration in two formats</h2><p>The example below describes a service, a boolean flag and an owner. The owner ID is text: its leading zeroes matter. Both representations can describe those values. YAML adds a comment and uses indentation for the nested mapping; JSON makes the object structure explicit with braces and commas.</p>'''+code_example('YAML configuration',FIXTURES['yaml'][0]['input'])+code_example('The same supported data in JSON',json.dumps(FIXTURES['yaml'][0]['expected'],indent=2))+'''<p>Formatting is not the data model. A newline, a comment or a different quote style can make a file easier to maintain without becoming a value that an application receives. Conversely, removing quotes from a value can change its type in some schemas. Before converting configuration, identify which values must stay strings, numbers, booleans, arrays or mappings.</p></section>'''
 body+=demo('yaml',copy)
 body+='''<section class="guide-section" id="type-rules"><h2>Syntax is only part of the difference</h2><p>This guide’s examples use the YAML 1.2 core schema and JSON values supported by the ParseCove converter. YAML processors can use other schemas, tags and version conventions. A result from a YAML 1.1 application is not automatically interchangeable with one from a 1.2 core parser.</p><div class="table-wrap"><table><thead><tr><th>Concern</th><th>YAML 1.2 core example</th><th>JSON representation or decision</th></tr></thead><tbody><tr><td>Boolean</td><td><code>enabled: true</code></td><td><code>{"enabled":true}</code></td></tr><tr><td>yes / no</td><td><code>answer: yes</code></td><td><code>{"answer":"yes"}</code> here; do not assume YAML 1.1 behavior</td></tr><tr><td>Identifier</td><td><code>id: "001"</code></td><td>Keep <code>"001"</code> as text</td></tr><tr><td>Date-looking text</td><td><code>date: 2026-11-27</code></td><td>A string with this schema, not a JSON Date type</td></tr><tr><td>Missing-like value</td><td><code>missing: null</code></td><td><code>null</code>, different from <code>""</code> and an absent member</td></tr><tr><td>Sequence</td><td><code>items: [red, blue]</code></td><td>An array of two strings</td></tr><tr><td>Mapping key</td><td><code>"1": first</code></td><td>JSON member names are strings; make that intent explicit</td></tr></tbody></table></div><p>JSON has a compact set of value types; it does not define a native date, comment, alias or non-finite number. A parser may additionally restrict integer precision or duplicate members. ParseCove rejects duplicate keys and integers outside the JavaScript safe integer range in these tools, rather than silently selecting or rounding a value. That is a stated conversion policy, not a claim that every JSON processor behaves identically.</p><p class="guide-source">References: <a href="https://yaml.org/spec/1.2.2/">YAML 1.2.2 specification</a> and <a href="https://www.rfc-editor.org/rfc/rfc8259">RFC 8259: JSON values and interoperability</a>.</p></section>
<section class="guide-section" id="conversion-loss"><h2>What a data conversion can lose</h2><p>Conversion keeps the supported values, not the original document. YAML comments, spacing, quote choices, block styles and source formatting do not survive as JSON values. Reverse conversion can create a readable YAML document, but cannot reconstruct comments that were discarded. Do not use a round trip as a source-file formatter if you need presentation preserved.</p><p>An alias such as <code>secondary: *colors</code> can refer to an earlier sequence. JSON can repeat the sequence’s values, but it has no anchor notation or shared-reference identity. A cyclic alias cannot become a finite JSON value tree. This tool also rejects excessive alias expansion, multiple documents, merge keys and unsupported tags; split or normalize those inputs deliberately before conversion.</p><div class="table-wrap"><table><thead><tr><th>Input feature</th><th>What to verify</th></tr></thead><tbody><tr><td>Comments and layout</td><td>Retain the original file if maintainers need its explanations</td></tr><tr><td>Duplicate keys</td><td>Choose the intended value at the source; do not depend on an overwrite rule</td></tr><tr><td>Aliases</td><td>Check expansion, size and whether identity has meaning to the application</td></tr><tr><td>Large integer IDs</td><td>Quote exact identifiers before passing through number-based tooling</td></tr><tr><td>Tags or application-specific types</td><td>Decide on an explicit JSON representation with the consuming application</td></tr></tbody></table></div><p>A successful conversion checks the format and supported value model. It does not prove that a Kubernetes manifest, CI pipeline or application configuration satisfies its own schema. Validate the converted document with the consuming application as a separate step.</p></section>
<section class="guide-section" id="choose-format"><h2>Choose the format around the workflow</h2><p>For a file maintained by people, comments, readable nesting and familiar team conventions may favor YAML. The same flexibility also makes parser version, indentation and implicit type rules important review topics. For program-to-program exchange, JSON’s small value model and widespread parsers can make the contract easier to specify. Neither format automatically makes the contained data accurate or appropriate for an application.</p><p>Ask three concrete questions: Who edits this file? Which parser and schema reads it? Which values must retain their type and exact text? Keep the original document during migration, compare representative parsed values, and check the receiving application’s requirements before replacing configuration.</p><p>Use the <a href="/yaml-to-json/">YAML ↔ JSON converter</a> to try your own supported document. Both <code>.yaml</code> and <code>.yml</code> file extensions are accepted; the extension alone does not establish a version or schema. For rectangular records, the <a href="/csv-to-json/">CSV ↔ JSON tool</a> makes a different set of choices about headers, strings and empty cells. If an API gives you a string containing JSON instead of an object, see <a href="/guides/json-double-encoding/">the JSON encoding-layer guide</a>.</p></section>'''
 body+='<p class="guide-note">Once you have a JSON document, use <a href="/json-minify/">JSON minify and format</a> to change its layout, or <a href="/json-compare/">compare JSON values</a> to inspect differences between two versions. Formatting a document and decoding a string are separate operations.</p>'
 body+='<section class="guide-section faq" id="format-faq"><h2>Common questions</h2>'+''.join(faq(q,a) for q,a in [
 ('Is JSON valid YAML?','YAML 1.2 was designed for JSON compatibility, but the parser, schema, accepted constructs and interoperability policies still matter. Do not infer that every JSON implementation and every YAML configuration system accept or resolve all inputs the same way.'),
 ('Is YAML always better for configuration?','No. Follow the consuming application’s supported format and your team’s editing workflow. Comments can help humans, while a narrow data contract can reduce interpretation choices. Validate the actual schema either way.'),
 ('Why did a date or yes/no change type in another program?','A different YAML version, schema or explicit tag may resolve the scalar differently. These examples use 1.2 core, where yes stays text and untagged date-looking values stay strings. Quote exact text and document the parser assumptions.'),
 ('Can conversion preserve comments?','A value conversion to ordinary JSON cannot store YAML comments as comments. Keep the original source or use a document-aware editing workflow when presentation matters.'),
 ])+'</section></article>'
 return body

def json_encoding_guide(code_example,faq,copy):
 body=header('json-double-encoding','JSON encoding layers',EXTRA_GUIDES[1]['heading'],'Backslashes can be necessary JSON syntax, real characters in a value, or evidence that a document was serialized into a string. Inspect the value and its expected type before changing it.',[('four-states','Four states'),('format-lab','Inspect a layer'),('decode-deliberately','Decode deliberately'),('keep-data','Keep real data'),('fix-producer','Fix the producer'),('format-faq','FAQ')])
 body+='''<section class="guide-section" id="four-states"><h2>Separate the value from its representation</h2><p>An object in memory is not the same thing as JSON source text. Serializing the object produces a document. Serializing that document as a string adds another layer: its quote and backslash characters must be escaped to fit inside a JSON string. A debugger may also display a string with escapes without changing the stored value.</p><div class="table-wrap"><table><thead><tr><th>State</th><th>Complete example</th><th>What to inspect</th></tr></thead><tbody><tr><td>JSON object document</td><td><code>{"id":"001"}</code></td><td>Parsing returns an object</td></tr><tr><td>JSON string containing that document</td><td><code>"{\u005c"id\u005c":\u005c"001\u005c"}"</code></td><td>Parsing returns a string, whose contents are JSON text</td></tr><tr><td>Ordinary string value</td><td><code>"001"</code></td><td>The leading zeroes are data, not a reason to parse again</td></tr><tr><td>Debugger or log representation</td><td>A quoted display of a string</td><td>Check raw text and the runtime type; do not count visible slashes alone</td></tr></tbody></table></div><p>The first two examples can describe related information while having different top-level types. A formatter may correctly leave the second as a string: formatting is not permission to rewrite the application’s data model. A document may also contain just one field holding JSON text, while its other strings should stay untouched.</p></section>'''
 body+=demo('json',copy)
 body+='''<section class="guide-section" id="decode-deliberately"><h2>Decode one known layer, then check the result</h2><p>The sample below deliberately serializes an object twice. The first parse returns a string; the second returns the known original object. This is a demonstration of a controlled input, not a general instruction to keep parsing arbitrary values until they stop looking like JSON.</p>'''+code_example('JavaScript: a deliberately double-encoded sample',JS_SNIPPET).replace('<pre><code>','<pre><code id="json-layer-js">')+code_example('Python: the same known layers',PY_SNIPPET).replace('<pre><code>','<pre><code id="json-layer-python">')+'''<p>For a production response, check the producer’s contract first. If the field is documented as an object, fix duplicate serialization upstream where possible. If it is explicitly documented as JSON text, decode that identified field when needed. Do not automatically parse every string in a tree: even a string containing valid object syntax may be a template, an example, a signed body or ordinary text.</p>'''+code_example('Decode an identified payload field',FIELD_SNIPPET).replace('<pre><code>','<pre><code id="json-layer-field">')+'''<p>The <a href="/json-unescape/">JSON unescape tool</a> handles one string layer at a time. Choose Complete string when the outer double quotes are present, or String content when the copied fragment omits them. Its result is text; it does not silently traverse an object and change the types of nested fields.</p></section>
<section class="guide-section" id="keep-data"><h2>Why deleting backslashes can corrupt the data</h2><p>JSON uses escapes to represent quotes, reverse solidus characters and control characters inside strings. A path containing real backslashes needs an escaped source representation. A newline in the value is represented by a backslash-n sequence in JSON source; an actual unescaped line feed between the source string’s quotes is invalid.</p>'''+code_example('A valid document with real path characters and a newline',FIXTURES['json'][3]['input'])+'''<p>After parsing, the path contains its actual separators and the message contains a newline. Removing every backslash from the source changes those values or breaks the document. Likewise, replacing every escaped quote can turn a quote inside a value into an accidental end-of-string character. A valid escape is not evidence of a problem.</p><p>Preserve exact identifiers as strings. Values such as <code>"001"</code>, <code>"true"</code> and <code>"null"</code> can intentionally be text. Numeric IDs beyond a parser’s exact range need special care before any number conversion. The data tools on this site reject unsafe integer literals; this inspector uses the same strict JSON checks.</p><p class="guide-source">References: <a href="https://www.rfc-editor.org/rfc/rfc8259">RFC 8259, especially strings and interoperability</a> and <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/JSON/parse">MDN: JSON.parse</a>.</p></section>
<section class="guide-section" id="fix-producer"><h2>Fix the extra serialization at its source</h2><p>Trace where an object becomes text. A common extra layer appears when application code serializes a value and then hands the resulting string to a response helper that serializes again. Structured logs and message envelopes may intentionally store a JSON document inside a string field. The right fix depends on that contract, not on the number of visible backslashes.</p><ol><li>Inspect the raw response or log field and record its expected type.</li><li>Parse one known JSON document and check whether the returned value is an object, array or string.</li><li>If a documented string field holds another JSON document, decode that field deliberately for the consuming task.</li><li>When you control both ends, pass the intended value type through the boundary and serialize at the agreed layer.</li><li>Compare representative values before changing the producer or rewriting stored data.</li></ol><p>Do not rewrite signed payloads, templates or raw audit records merely to make their representation easier to read. Decode a copy for inspection and retain the original where its exact bytes matter. JSON escaping is also different from UTF-8 byte misdecoding, HTML entity encoding and URL encoding; this guide’s examples address JSON serialization layers, not every problem called “double encoding”.</p><p>When JSON text is stored inside one CSV cell, use the <a href="/csv-to-json/#nested-json-cells">CSV nested-value example</a> to distinguish a string cell from columns or rows expanded out of an object. For configuration syntax and types, see <a href="/guides/yaml-vs-json/">YAML vs JSON</a>.</p></section>'''
 body+='<p class="guide-note">Once you have a JSON document, use <a href="/json-minify/">JSON minify and format</a> to change its layout, or <a href="/json-compare/">compare JSON values</a> to inspect differences between two versions. Formatting a document and decoding a string are separate operations.</p>'
 body+='<section class="guide-section faq" id="format-faq"><h2>Common questions</h2>'+''.join(faq(q,a) for q,a in [
 ('Does a backslash always mean double encoding?','No. It may be required JSON syntax, an actual character in a string, or a display convention. Inspect the source and resulting value type. A path with escaped separators can be correct.'),
 ('Should I call JSON.parse twice?','Only when you know that the first parsed value is a string containing the next JSON document expected by your contract. The sample here is deliberately constructed that way. Do not apply a fixed number of parses to unrelated responses.'),
 ('Can I remove all escape characters?','There is no general operation that removes every escape while preserving every value. Parse the supported syntax at the correct layer. If the source is damaged, recover the intended original instead of deleting characters until it parses.'),
 ('Why does one field remain a string after parsing?', 'That is the type represented by the document. The field might intentionally contain JSON text, an identifier or an example. Decode only the identified field when the producer and consumer agree on that meaning.'),
 ])+'</section></article>'
 return body
